  ($s$8f8d20ba-b0af-4963-810c-7396c4941773$s$, $s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 0, $s$Tobago_Beaches$s$, $s$https://www.google.com/maps/embed?pb=!1m40!1m12!1m3!1d62602.293107024634!2d-60.69761350489427!3d11.287608406702049!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!4m25!3e0!4m5!1s0x8c4853e8fedee33d%3A0x1ef432cfd6352f48!2sCastara%20Bay%20Rd%2C%20Trinidad%20and%20Tobago!3m2!1d11.279954!2d-60.6950764!4m5!1s0x8c4853e87af0512b%3A0x9bb0b51268c22197!2sCastara%20Beach!3m2!1d11.279833!2d-60.695929899999996!4m5!1s0x8c485154b47f626b%3A0x26ea8ba399baf10a!2sEnglishmans%20Bay%2C%20Trinidad%20and%20Tobago!3m2!1d11.2918583!2d-60.6727874!4m5!1s0x8c4855caafa4f21b%3A0xf07a1bfe142e60ad!2sTobago%20Main%20Ridge%20Forest%20Reserve%2C%20Mason%20Hall%2C%20Trinidad%20and%20Tobago!3m2!1d11.2737713!2d-60.6168974!5e0!3m2!1sen!2sus!4v1754186428058!5m2!1sen!2sus$s$);
