INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 0, $s$itinerary_with_map$s$, $s${"itineraryId":"8f8d20ba-b0af-4963-810c-7396c4941773"}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 1, $s$text$s$, $s${"html":"As I mentioned in my insider tip, Tobago deserves more of your time if you're seeking a more laid-back pace focusing on beaches, rainforests, and relaxation. \nWe debated between the ⛴️ ferry and a 🛩️ flight but ultimately chose the ferry. We believed that savoring the journey, with its scenic views of the islands, was an integral part of the travel experience. Plus, the ferry ride wasn't significantly longer than a flight. We opted for the early morning ferry (6 AM) from Trinidad."}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 2, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1949","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1945","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1946","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1771"]}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 3, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1773","leftImageAlt":"img1773","html":"While sometimes prone to delays, the four-hour ferry ride offered a unique perspective, gliding past small, uninhabited islands as we sailed toward our destination. Upon arriving in Tobago, we collected our 🚙rental car and headed towards our hotel, but not before indulging in a delicious local lunch at a charming roadside eatery. This was the perfect start to our island adventure."}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 4, $s$text$s$, $s${"html":"The drive to 📌Castara Bay was an adventure in itself. The winding road demanded patience as we navigated past slow-moving buses and trucks."}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 5, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1814","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1816","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1817","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1819"]}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 6, $s$text$s$, $s${"html":"As we approached, the bay's beauty began to unfold, culminating in a breathtaking panorama. Castara Beach captivated us with its crescent shape and the unusual underwater shelf, creating a gradual and inviting entry into the turquoise waters. We couldn't wait to explore this idyllic corner of paradise.\nFrom there, we continued to explore another secluded beach, 📌Englishman's Bay, a hidden gem. This secluded paradise captivated us with its pristine white sand, crystal-clear turquoise waters, and a backdrop of lush green hills."}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 7, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1830","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1831","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1832","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1837","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1839","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1841","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1845","aroundtheworld50s/blog/trinidad-and-tobago/5/IMG_1824"]}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 8, $s$text$s$, $s${"html":"We reluctantly left the idyllic bay, eager to explore more before the fading light made driving on the winding roads too challenging. We headed to the 📌Main Ridge Forest Reserve🌲, the oldest protected rainforest in the Western Hemisphere. The drive through the lush green hills was a journey, offering glimpses of the island's diverse wildlife. We reached the reserve, and the air immediately felt cooler and fresher. The sounds of the rainforest created a sense of tranquility. We couldn’t spend more than an hour exploring the part of the trail (ℹ️ moderately difficult hike).\n As the light began to fade, we decided against continuing to 📌Argyle Falls. Driving on the winding roads with narrow shoulders in the dark presented a safety concern we weren't willing to risk.  💥 I recommend dedicating at least half a day to the forest."}$s$::jsonb),
  ($s$3893cddc-f455-4ac8-9e80-7cfe18b7037c$s$, 9, $s$text$s$, $s${"html":"Tobago offers a diverse culinary scene, with many charming, smaller restaurants showcasing the island's unique flavors. To ensure a delightful dining experience, making reservations in advance is highly recommended, as these popular spots tend to fill up quickly."}$s$::jsonb);
